--
-- Name: calculate_json_diff(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_json_diff(old_data jsonb, new_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    result JSONB := '{}';
    key TEXT;
BEGIN
    -- Find changed and added keys
    FOR key IN SELECT jsonb_object_keys(new_data) LOOP
        IF old_data->key IS DISTINCT FROM new_data->key THEN
            result := result || jsonb_build_object(key, jsonb_build_object(
                'old', old_data->key,
                'new', new_data->key
            ));
        END IF;
    END LOOP;
    
    -- Find removed keys
    FOR key IN SELECT jsonb_object_keys(old_data) LOOP
        IF NOT new_data ? key THEN
            result := result || jsonb_build_object(key, jsonb_build_object(
                'old', old_data->key,
                'new', null
            ));
        END IF;
    END LOOP;
    
    RETURN result;
END;
$$;


--
-- Name: cleanup_old_audit_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_audit_logs() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INTEGER := 0;
    v_row_count INTEGER;
    r RECORD;
BEGIN
    FOR r IN SELECT category, retention_days FROM multi_framework_audit_retention LOOP
        DELETE FROM multi_framework_audit_log
        WHERE action IN (
            SELECT code FROM multi_framework_audit_actions WHERE category = r.category
        )
        AND created_at < NOW() - (r.retention_days || ' days')::INTERVAL;
        
        GET DIAGNOSTICS v_row_count = ROW_COUNT;
        deleted_count := deleted_count + v_row_count;
    END LOOP;
    
    RETURN deleted_count;
END;
$$;


