--

CREATE FUNCTION public.conversations_update_search_vector() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.search_vector :=
    setweight(to_tsvector('simple', coalesce(NEW.title, '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(NEW.last_message_preview, '')), 'B');
  RETURN NEW;
END;
$$;


--
-- Name: generate_partner_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_partner_referral_code() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_code VARCHAR(50);
    code_exists BOOLEAN;
BEGIN
    -- Only generate if not already set
    IF NEW.referral_code IS NULL THEN
        LOOP
            -- Generate code: PARTNER-XXXXXX (6 random alphanumeric chars)
            new_code := 'PARTNER-' || upper(substring(md5(random()::text) from 1 for 6));
            
            -- Check if exists
            SELECT EXISTS(SELECT 1 FROM partner_organizations WHERE referral_code = new_code) INTO code_exists;
            
            EXIT WHEN NOT code_exists;
        END LOOP;
        
        NEW.referral_code := new_code;
    END IF;
    
    -- Also generate slug if not set
    IF NEW.referral_link_slug IS NULL THEN
        NEW.referral_link_slug := lower(replace(NEW.referral_code, '-', ''));
    END IF;
    
    RETURN NEW;
END;
$$;


