--
-- Name: llm_logs_compat_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.llm_logs_compat_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_at IS NULL THEN NEW.created_at := COALESCE(NEW."timestamp", CURRENT_TIMESTAMP); END IF;
  IF NEW.total_tokens IS NULL THEN NEW.total_tokens := COALESCE(NEW.tokens_in, 0) + COALESCE(NEW.tokens_out, 0); END IF;
  IF NEW.error IS NULL AND NEW.error_message IS NOT NULL THEN NEW.error := NEW.error_message; END IF;
  IF NEW.tokens_used IS NULL THEN NEW.tokens_used := COALESCE(NEW.tokens_in, 0) + COALESCE(NEW.tokens_out, 0); END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_mf_audit(text, text, text, text, jsonb, jsonb, text, inet, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_mf_audit(p_assessment_id text, p_framework text, p_action text, p_actor_id text, p_old_data jsonb DEFAULT NULL::jsonb, p_new_data jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_diff JSONB;
    v_id BIGINT;
    v_actor_name VARCHAR;
    v_actor_email VARCHAR;
    v_project_id TEXT;
    v_org_id TEXT;
BEGIN
    -- Calculate diff
    IF p_old_data IS NOT NULL AND p_new_data IS NOT NULL THEN
        v_diff := calculate_json_diff(p_old_data, p_new_data);
    ELSE
        v_diff := NULL;
    END IF;
    
    -- Get actor details
    SELECT first_name || ' ' || last_name, email 
    INTO v_actor_name, v_actor_email
    FROM users WHERE id = p_actor_id;
    
    -- Get assessment context
    IF p_assessment_id IS NOT NULL THEN
        SELECT project_id, organization_id 
        INTO v_project_id, v_org_id
        FROM multi_framework_assessments WHERE id = p_assessment_id;
    END IF;
    
    -- Insert audit log
    INSERT INTO multi_framework_audit_log (
        assessment_id, framework, action, actor_id, actor_name, actor_email,
        old_data, new_data, diff, project_id, organization_id,
        ip_address, user_agent, notes
    ) VALUES (
        p_assessment_id, p_framework, p_action, p_actor_id, v_actor_name, v_actor_email,
        p_old_data, p_new_data, v_diff, v_project_id, v_org_id,
        p_ip_address, p_user_agent, p_notes
    ) RETURNING id INTO v_id;
    
    RETURN v_id;
END;
$$;


