--
-- Name: search_knowledge_embeddings(public.vector, double precision, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_knowledge_embeddings(query_embedding public.vector, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 5, filter_source_type character varying DEFAULT NULL::character varying) RETURNS TABLE(id integer, document_id character varying, chunk_text text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.id,
        e.document_id,
        e.chunk_text,
        e.metadata,
        1 - (e.embedding <=> query_embedding) as similarity
    FROM ai_knowledge_embeddings e
    WHERE 
        (filter_source_type IS NULL OR e.source_type = filter_source_type)
        AND 1 - (e.embedding <=> query_embedding) > match_threshold
    ORDER BY e.embedding <=> query_embedding
    LIMIT match_count;
END;
$$;


--
-- Name: update_attribution_ltv(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_attribution_ltv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
        IF NEW.status = 'APPROVED' OR NEW.status = 'PAID' THEN
            UPDATE partner_attributions
            SET 
                lifetime_value = lifetime_value + NEW.gross_amount,
                total_commission_earned = total_commission_earned + NEW.commission_amount,
                updated_at = NOW()
            WHERE id = NEW.attribution_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: update_conversation_on_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_conversation_on_message() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE conversations 
    SET 
        message_count = message_count + 1,
        last_message_preview = LEFT(NEW.content, 200),
        last_message_at = NEW.created_at,
        updated_at = NOW()
    WHERE id = NEW.conversation_id;
    RETURN NEW;
END;
$$;


