    CONSTRAINT approval_workflows_workflow_type_check CHECK ((workflow_type = ANY (ARRAY['role_assignment'::text, 'api_key_creation'::text, 'data_access'::text, 'budget_increase'::text, 'user_invitation'::text, 'permission_change'::text, 'custom'::text])))
);


--
-- Name: area_assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.area_assessments (
    id text NOT NULL,
    assessment_id text NOT NULL,
    project_id text NOT NULL,
    organization_id text NOT NULL,
    axis_id text NOT NULL,
    area_id text NOT NULL,
    current_level bigint DEFAULT 1,
    target_level bigint DEFAULT 5,
    gap bigint,
    interview_date date,
    interviewee_name text,
    interviewee_role text,
    interview_notes text,
    key_quotes text DEFAULT '[]'::text,
    observed_tools text DEFAULT '[]'::text,
    observed_processes text DEFAULT '[]'::text,
    strengths text DEFAULT '[]'::text,
    weaknesses text DEFAULT '[]'::text,
    evidence_files text DEFAULT '[]'::text,
    ai_current_state_description text,
    ai_target_state_description text,
    ai_recommendations text DEFAULT '[]'::text,
    ai_risks text DEFAULT '[]'::text,
    ai_kpis text DEFAULT '[]'::text,
    priority text DEFAULT 'MEDIUM'::text,
    effort_estimate text,
    budget_estimate_pln double precision,
    created_by text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT area_assessments_current_level_check CHECK (((current_level >= 1) AND (current_level <= 7))),
    CONSTRAINT area_assessments_priority_check CHECK ((priority = ANY (ARRAY['CRITICAL'::text, 'HIGH'::text, 'MEDIUM'::text, 'LOW'::text]))),
    CONSTRAINT area_assessments_target_level_check CHECK (((target_level >= 1) AND (target_level <= 7)))
);


