--
-- Name: competency_usage_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.competency_usage_stats AS
 SELECT c.id AS capability_id,
    c.organization_id,
    c.name,
    c.category_id,
    count(DISTINCT cr.initiative_id) AS initiative_count,
    count(DISTINCT uc.user_id) AS user_count
   FROM ((public.capabilities c
     LEFT JOIN public.capability_requirements cr ON ((cr.capability_id = c.id)))
     LEFT JOIN public.user_capabilities uc ON ((uc.capability_id = c.id)))
  WHERE (c.is_active = true)
  GROUP BY c.id, c.organization_id, c.name, c.category_id;


