    started_at date,
    completed_at date,
    target_date date,
    rating bigint,
    notes text,
    skills_gained text DEFAULT '[]'::text,
    time_invested_hours numeric DEFAULT 0,
    estimated_hours numeric,
    priority text DEFAULT 'medium'::text,
    category text,
    tags text DEFAULT '[]'::text,
    certificate_url text,
    certificate_date date,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT learning_items_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT learning_items_progress_percent_check CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT learning_items_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT learning_items_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'in_progress'::text, 'completed'::text, 'abandoned'::text]))),
    CONSTRAINT learning_items_type_check CHECK ((type = ANY (ARRAY['course'::text, 'book'::text, 'certification'::text, 'workshop'::text, 'article'::text, 'video'::text, 'podcast'::text, 'other'::text])))
);


