CREATE VIEW public.v_feedback_with_analysis AS
 SELECT sf.id,
    sf.user_id,
    u.email AS user_email,
    sf.type,
    sf.message,
    sf.status,
    sf.created_at,
    fa.sentiment,
    fa.sentiment_score,
    fa.priority,
    fa.priority_score,
    fa.ai_summary,
    fa.categories_json,
    fa.keywords_json
   FROM ((public.system_feedback sf
     LEFT JOIN public.users u ON ((sf.user_id = u.id)))
     LEFT JOIN public.feedback_analysis fa ON ((sf.id = fa.feedback_id)));


--
-- Name: v_multi_framework_audit_recent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_multi_framework_audit_recent AS
 SELECT al.id,
    al.assessment_id,
    al.framework,
    al.action,
    al.action_category,
    al.actor_id,
    al.actor_name,
    al.actor_email,
    al.actor_role,
    al.old_data,
    al.new_data,
    al.diff,
    al.entity_type,
    al.entity_id,
    al.entity_name,
    al.project_id,
    al.organization_id,
    al.ip_address,
    al.user_agent,
    al.request_id,
    al.notes,
    al.tags,
    al.created_at,
    a.name AS assessment_name,
    ((u.first_name || ' '::text) || u.last_name) AS actor_full_name,
    aa.name AS action_name,
    aa.severity AS action_severity
   FROM (((public.multi_framework_audit_log al
     LEFT JOIN public.multi_framework_assessments a ON ((al.assessment_id = a.id)))
     LEFT JOIN public.users u ON ((al.actor_id = u.id)))
     LEFT JOIN public.multi_framework_audit_actions aa ON (((al.action)::text = (aa.code)::text)))
  ORDER BY al.created_at DESC;


--
-- Name: v_multi_framework_audit_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_multi_framework_audit_summary AS
 SELECT action,
    framework,
    count(*) AS count,
    min(created_at) AS first_occurrence,
    max(created_at) AS last_occurrence
   FROM public.multi_framework_audit_log
  GROUP BY action, framework
  ORDER BY (count(*)) DESC;


--
-- Name: v_partner_earnings_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_partner_earnings_summary AS
 SELECT po.id AS partner_org_id,
    po.name AS partner_name,
    po.tier,
    po.program_type,
    po.referral_code,
    count(DISTINCT pa.id) AS total_attributions,
    count(DISTINCT pa.id) FILTER (WHERE ((pa.status)::text = 'ACTIVE'::text)) AS active_customers,
    sum(pa.lifetime_value) AS total_customer_ltv,
    sum(pa.total_commission_earned) AS total_commission_earned,
    count(DISTINCT pct.id) AS total_transactions,
    sum(pct.commission_amount) FILTER (WHERE ((pct.status)::text = 'PENDING'::text)) AS pending_commission,
    sum(pct.commission_amount) FILTER (WHERE ((pct.status)::text = 'APPROVED'::text)) AS approved_commission,
    sum(pct.commission_amount) FILTER (WHERE ((pct.status)::text = 'PAID'::text)) AS paid_commission,
    sum(pp.net_amount) FILTER (WHERE ((pp.status)::text = 'COMPLETED'::text)) AS total_payouts
   FROM (((public.partner_organizations po
     LEFT JOIN public.partner_attributions pa ON ((pa.partner_org_id = po.id)))
     LEFT JOIN public.partner_commission_transactions pct ON ((pct.partner_org_id = po.id)))
     LEFT JOIN public.partner_payouts pp ON ((pp.partner_org_id = po.id)))
  GROUP BY po.id, po.name, po.tier, po.program_type, po.referral_code;


--
-- Name: v_partner_referral_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_partner_referral_funnel AS
 SELECT po.id AS partner_org_id,
    po.name AS partner_name,
    po.referral_code,
    count(prc.id) AS total_clicks,
    count(DISTINCT prc.id) FILTER (WHERE (prc.converted = true)) AS signups,
    count(DISTINCT pa.id) FILTER (WHERE ((pa.status)::text = 'PENDING'::text)) AS trials,
    count(DISTINCT pa.id) FILTER (WHERE ((pa.status)::text = 'ACTIVE'::text)) AS paid_customers,
    round((((count(DISTINCT pa.id) FILTER (WHERE ((pa.status)::text = 'ACTIVE'::text)))::numeric * 100.0) / (NULLIF(count(prc.id), 0))::numeric), 2) AS conversion_rate
   FROM ((public.partner_organizations po
     LEFT JOIN public.partner_referral_clicks prc ON ((prc.partner_org_id = po.id)))
     LEFT JOIN public.partner_attributions pa ON ((pa.partner_org_id = po.id)))
  GROUP BY po.id, po.name, po.referral_code;


--
-- Name: v_pulse_daily_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pulse_daily_summary AS
 SELECT date(created_at) AS date,
    count(*) AS total_responses,
    avg(rating) AS avg_rating,
    sum(
        CASE
            WHEN (rating <= 2) THEN 1
            ELSE 0
        END) AS detractors,
    sum(
        CASE
            WHEN (rating = 3) THEN 1
            ELSE 0
        END) AS passives,
    sum(
        CASE
            WHEN (rating >= 4) THEN 1
            ELSE 0
        END) AS promoters
   FROM public.feedback_pulse
  GROUP BY (date(created_at))
  ORDER BY (date(created_at)) DESC;


