--
-- Name: v_feature_requests_leaderboard _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_feature_requests_leaderboard AS
 SELECT fr.id,
    fr.feature_name,
    fr.description,
    fr.category,
    fr.impact,
    fr.status,
    fr.votes_count,
    fr.created_at,
    count(DISTINCT fv.user_id) AS unique_voters
   FROM (public.feature_requests fr
     LEFT JOIN public.feature_votes fv ON ((fr.id = fv.feature_id)))
  WHERE (fr.status <> ALL (ARRAY['REJECTED'::text, 'COMPLETED'::text]))
  GROUP BY fr.id
  ORDER BY fr.votes_count DESC, fr.created_at DESC;


